type Rules = typeof MOVEMENT_RULES;

const round1 = (m: number) => Math.round(m * 10) / 10;

/**
 * Verified distance for movement points, computed server-side from first-party evidence for every run,
 * public or private. Mocked locations void the whole run. Distance is never bridged across a recording
 * gap or a pause, and stretches that look like a vehicle (sustained speed beyond running) or a GPS jump
 * are left out rather than rejecting the rest of an honest run.
 */
export function evaluateMovement(raw: readonly LocationSample[], events: readonly RecordingEvent[], rules: Rules = MOVEMENT_RULES): MovementEvaluation {
  const samples = canonicalSamples(raw);
  const none = { verifiedDistanceM: 0, excludedDistanceM: 0, ruleVersion: rules.version };
  if (samples.some((s) => s.mocked)) return { decision: 'invalid', reasons: ['mock_location'], ...none };
  const usable = samples.filter((s) => isUsable(s));
  if (usable.length < rules.minSamples.value) return { decision: 'unranked', reasons: ['insufficient_samples'], ...none };

  const pauses = pausedIntervals(events, usable[usable.length - 1]!.t);
  const paused = (t: number) => pauses.some((p) => t > p.startT && t <= p.endT);

  interface Segment { d: number; dt: number; skip: boolean; jump: boolean; fast: boolean }
  const segments: Segment[] = [];
  for (let i = 1; i < usable.length; i++) {
    const a = usable[i - 1]!;
    const b = usable[i]!;
    const dt = (b.t - a.t) / 1000;
    if (dt <= 0) continue;
    const d = haversineMeters(a, b);
    const skip = dt > rules.maxCountedGapSeconds.value || paused(b.t);
    const v = d / dt;
    segments.push({ d, dt, skip, jump: !skip && v > rules.maxJumpSpeedMetersPerSecond.value, fast: !skip && v > rules.vehicleSpeedMetersPerSecond.value });
  }

  // A vehicle stretch is a contiguous run of fast segments lasting at least the sustained threshold.
  const vehicle: boolean[] = segments.map(() => false);
  let from = -1;
  let seconds = 0;
  const close = (end: number) => {
    if (from >= 0 && seconds >= rules.vehicleSustainedSeconds.value) for (let k = from; k < end; k++) vehicle[k] = true;
    from = -1;
    seconds = 0;
  };
  segments.forEach((s, i) => {
    if (s.fast) {
      if (from < 0) from = i;
      seconds += s.dt;
    } else close(i);
  });
  close(segments.length);

  let verified = 0;
  let excluded = 0;
  segments.forEach((s, i) => {
    if (s.skip) return;
    if (s.jump || vehicle[i]) excluded += s.d;
    else verified += s.d;
  });
  const reasons = new Set<ReasonCode>();
  if (vehicle.some(Boolean)) reasons.add('suspicious_speed');
  if (segments.some((s, i) => s.jump && !vehicle[i])) reasons.add('gps_jump');
  if (verified < rules.minVerifiedDistanceMeters.value) {
    reasons.add('movement_too_short');
    return { decision: 'unranked', reasons: [...reasons], verifiedDistanceM: 0, excludedDistanceM: round1(excluded), ruleVersion: rules.version };
  }
  return { decision: 'eligible', reasons: [...reasons], verifiedDistanceM: round1(verified), excludedDistanceM: round1(excluded), ruleVersion: rules.version };
}

/** Points for a verified distance (whole points, rounded down) before the server's daily cap. */
export function pointsForDistance(verifiedDistanceM: number, pointsPerKm: number = MOVEMENT_RULES.pointsPerKm.value): number {
  return Math.max(0, Math.floor((Math.max(0, verifiedDistanceM) * pointsPerKm) / 1000));
}

/** Average H3 cell area in m² by resolution (Uber H3 published averages). */
export const H3_AVERAGE_CELL_AREA_M2: Readonly<Record<number, number>> = { 9: 105_332.513, 10: 15_047.502, 11: 2_149.643, 12: 307.092 };

/** Reclaim cost of one cell: proportional to its area so the price of ground does not depend on the grid. */
export function reclaimCostPerCell(resolution: number, per1000SquareMeters: number = MOVEMENT_RULES.reclaimPointsPer1000SquareMeters.value): number {
  const area = H3_AVERAGE_CELL_AREA_M2[resolution] ?? H3_AVERAGE_CELL_AREA_M2[11]!;
  return Math.max(1, Math.ceil((area / 1000) * per1000SquareMeters));
}

export interface ReclaimQuote {
  cells: number;
  costPerCell: number;
  total: number;
  balance: number;
  remaining: number;
  affordable: boolean;
}

/** What a reclaim of `cells` would cost against `balance` (the server re-checks everything). */
export function quoteReclaim(cells: number, costPerCell: number, balance: number): ReclaimQuote {
  const total = Math.max(0, cells) * costPerCell;
  return { cells, costPerCell, total, balance, remaining: balance - total, affordable: cells > 0 && total <= balance };
}

export type BadgeTier = 'bronze' | 'silver' | 'gold' | 'platinum';
export type ChallengeCategory = 'distance' | 'consistency' | 'territory' | 'exploration' | 'community' | 'competitive';

/**
 * Achievement score (the global ranking): tier points of every completed challenge plus a bonus for
 * each category with at least one badge. Movement points never enter this formula.
 */
export function achievementScore(
  badges: ReadonlyArray<{ tier: BadgeTier; category: ChallengeCategory }>,
  tierPoints: Readonly<Record<BadgeTier, number>> = ACHIEVEMENT_RULES.tierPoints.value,
  categoryBonus: number = ACHIEVEMENT_RULES.categoryBonus.value
): { score: number; tierTotal: number; categories: number; bonus: number } {
  const tierTotal = badges.reduce((t, b) => t + (tierPoints[b.tier] ?? 0), 0);
  const categories = new Set(badges.map((b) => b.category)).size;
  return { score: tierTotal + categories * categoryBonus, tierTotal, categories, bonus: categories * categoryBonus };
}
